#include "unity.h"
#include "buffer.h"
#include "helpers.h"
#include <stdio.h>
#include <string.h>

void setUp(void) { }
void tearDown(void) { }

void unit_test_buffer_print_basic_hex_output(void) {
    // Setup: create a buffer with known binary content
    // We'll use 10 bytes: 0x01, 0x23, 0x45, 0x67, 0x89, 0xab, 0xcd, 0xef, 0x10, 0x20
    unsigned char raw_data[10] = {0x01, 0x23, 0x45, 0x67, 0x89, 0xab, 0xcd, 0xef, 0x10, 0x20};
    // Create a string with these bytes for helper_create_buffer_with_content
    char content[11];
    memcpy(content, raw_data, 10);
    content[10] = '\0'; // Null-terminate for safety

    buffer_t *buf = helper_create_buffer_with_content(content);
    TEST_ASSERT_NOT_NULL(buf);
    // Overwrite the buffer's alloc with our raw_data for exact byte values
    free(buf->alloc);
    buf->alloc = (char*)raw_data;
    buf->len = 10;

    // Redirect stdout to a buffer to capture output
    char output[256] = {0};
    FILE *orig_stdout = stdout;
    FILE *capture = tmpfile();
    TEST_ASSERT_NOT_NULL(capture);
    fflush(stdout);
    int saved_fd = dup(fileno(stdout));
    dup2(fileno(capture), fileno(stdout));

    // Test: call buffer_print
    buffer_print(buf);

    // Restore stdout
    fflush(stdout);
    dup2(saved_fd, fileno(stdout));
    close(saved_fd);

    // Read output from capture
    fseek(capture, 0, SEEK_SET);
    size_t n = fread(output, 1, sizeof(output) - 1, capture);
    output[n] = '\0';
    fclose(capture);

    // Expected output:
    // "
  01 23 45 67 89 ab cd ef
  10 20
"
    const char *expected =
        "
  01 23 45 67 89 ab cd ef
  10 20
";

    TEST_ASSERT_EQUAL_STRING(expected, output);

    // Cleanup
    buf->alloc = NULL; // Prevent double-free since alloc now points to stack
    buffer_free(buf);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_buffer_print_basic_hex_output);
    return UNITY_END();
}


